<template>
  <div class="admin-shell"><AppNav />
    <main class="admin-page">
      <section class="hero"><p class="eyebrow">ADMIN CONSOLE</p><h1>平台管理后台</h1><p>账户、公告与关键操作审计均在这里集中管理。</p></section>
      <el-tabs v-model="tab">
        <el-tab-pane label="公告管理" name="announcements">
          <div class="toolbar"><p>登录页与右上角通知中心会同步显示已发布的公告。</p><button class="primary" @click="openAnnouncement()">发布公告</button></div>
          <section v-for="item in data.announcements" :key="item.id" class="announcement-card"><div><b>{{ item.is_pinned ? '📌 置顶 · ' : '' }}{{ item.title }}</b><p>{{ item.content }}</p><small>更新于 {{ format(item.updated_at) }} · {{ item.author_name }}</small></div><aside><button class="secondary" @click="openAnnouncement(item)">编辑</button><button class="danger" @click="removeAnnouncement(item)">删除</button></aside></section>
          <p v-if="!data.announcements.length" class="empty">暂未发布公告。</p>
        </el-tab-pane>
        <el-tab-pane :label="`账户管理 (${data.users.length})`" name="users">
          <div class="table-wrap"><el-table :data="data.users" stripe><el-table-column prop="name" label="用户" min-width="120"><template #default="s"><b>{{ s.row.name }}</b><small class="block">{{ s.row.student_id }}</small></template></el-table-column><el-table-column prop="college" label="学院/班级" min-width="170"><template #default="s">{{ s.row.college }}<small class="block">{{ s.row.class }}</small></template></el-table-column><el-table-column label="状态" width="100"><template #default="s"><span :class="['status',s.row.account_status==='disabled'?'off':'on']">{{ s.row.account_status==='disabled'?'已停用':'正常' }}</span></template></el-table-column><el-table-column label="操作" min-width="270"><template #default="s"><template v-if="s.row.role!=='admin'"><button class="secondary" @click="openUserAction(s.row,s.row.account_status==='disabled'?'enable':'disable')">{{ s.row.account_status==='disabled'?'启用':'停用' }}</button><button class="secondary" @click="openUserAction(s.row,'reset')">重置密码</button><button class="danger" @click="openUserAction(s.row,'delete')">删除</button></template><small v-else>管理员账户受保护</small></template></el-table-column></el-table></div>
        </el-tab-pane>
        <el-tab-pane :label="`注销申请 (${pendingCount})`" name="requests">
          <section v-for="item in data.requests" :key="item.id" class="request-card"><div><b>{{ item.name || '已删除用户' }} · {{ item.student_id }}</b><p>申请时间：{{ format(item.requested_at) }}　状态：{{ item.status }}</p><p v-if="item.note">备注：{{ item.note }}</p></div><aside v-if="item.status==='pending'"><button class="secondary" @click="openUserAction(item,'disable')">停用</button><button class="danger" @click="openUserAction(item,'delete')">审核并删除</button></aside></section><p v-if="!data.requests.length" class="empty">暂无账户注销申请。</p>
        </el-tab-pane>
        <el-tab-pane label="操作日志" name="logs"><div class="table-wrap"><el-table :data="data.logs" stripe><el-table-column label="时间" width="180"><template #default="s">{{ format(s.row.created_at) }}</template></el-table-column><el-table-column prop="actor_name" label="操作人" width="120"/><el-table-column prop="action" label="操作" width="190"/><el-table-column label="目标" width="130"><template #default="s">{{ s.row.target_student_id || s.row.target_name || '-' }}</template></el-table-column><el-table-column prop="detail" label="说明" min-width="220"/></el-table></div></el-tab-pane>
      </el-tabs>
    </main>
    <el-dialog v-model="announcementDialog" :title="editAnnouncement.id?'编辑公告':'发布公告'" width="min(560px,92vw)"><el-form label-position="top"><el-form-item label="公告标题"><el-input v-model="editAnnouncement.title" maxlength="80" show-word-limit /></el-form-item><el-form-item label="公告内容"><el-input v-model="editAnnouncement.content" type="textarea" :rows="6" maxlength="2000" show-word-limit /></el-form-item><el-checkbox v-model="editAnnouncement.is_pinned">置顶显示</el-checkbox></el-form><template #footer><button class="secondary" @click="announcementDialog=false">取消</button><button class="primary" @click="saveAnnouncement">保存公告</button></template></el-dialog>
    <el-dialog v-model="userActionDialog" :title="actionTitle" width="min(520px,92vw)" :close-on-click-modal="false"><div class="warning-box">你正在对 <b>{{ actionTarget?.name }}（{{ actionTarget?.student_id }}）</b>执行“{{ actionLabel }}”。{{ actionType==='delete'?'删除后该用户的个人资料、学习记录和个人上传资料将无法恢复。':actionType==='reset'?'旧密码不会被显示或导出；请设置一个临时密码并通过线下方式告知该用户。':'停用后该用户无法继续登录。' }}</div><el-checkbox v-model="actionUnderstood">我已确认操作对象与后果</el-checkbox><el-form label-position="top" class="action-form"><el-form-item v-if="actionType==='reset'" label="新临时密码（8 至 128 位）"><el-input v-model="resetPassword" type="password" show-password autocomplete="new-password" /></el-form-item><el-form-item label="操作原因（建议填写）"><el-input v-model="actionReason" type="textarea" :rows="3" maxlength="300" show-word-limit /></el-form-item><el-form-item :label="`请输入“${actionConfirmText}”完成第二次确认`"><el-input v-model="actionTyped" :placeholder="actionConfirmText" /></el-form-item></el-form><template #footer><button class="secondary" @click="userActionDialog=false">取消</button><button class="danger" :disabled="!actionUnderstood || actionBusy" @click="runUserAction">确认{{ actionLabel }}</button></template></el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import AppNav from '../components/AppNav.vue'
import { api } from '../utils/api'
const router=useRouter(),tab=ref('announcements'),data=ref({users:[],requests:[],announcements:[],logs:[]}),announcementDialog=ref(false),editAnnouncement=ref({}),userActionDialog=ref(false),actionTarget=ref(null),actionType=ref(''),actionReason=ref(''),actionTyped=ref(''),resetPassword=ref(''),actionUnderstood=ref(false),actionBusy=ref(false)
const pendingCount=computed(()=>data.value.requests.filter(item=>item.status==='pending').length)
const actionLabel=computed(()=>({disable:'停用账户',enable:'启用账户',reset:'重置密码',delete:'删除账户'})[actionType.value]||'操作')
const actionConfirmText=computed(()=>({disable:'停用账户',enable:'启用账户',reset:'重置密码',delete:'删除账户'})[actionType.value]||'')
const actionTitle=computed(()=>`二次确认：${actionLabel.value}`)
const format=value=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'-'
async function load(){try{data.value=await api('/admin/overview')}catch(error){ElMessage.error(error.message);router.replace('/dashboard')}}
function openAnnouncement(item){editAnnouncement.value=item?{...item,is_pinned:!!item.is_pinned}:{title:'',content:'',is_pinned:true};announcementDialog.value=true}
async function saveAnnouncement(){const item=editAnnouncement.value;if(!item.title?.trim()||!item.content?.trim())return ElMessage.warning('请填写公告标题和内容');try{const result=item.id?await api(`/admin/announcements/${item.id}`,{method:'PATCH',body:JSON.stringify(item)}):await api('/admin/announcements',{method:'POST',body:JSON.stringify(item)});ElMessage.success(result.message);announcementDialog.value=false;await load()}catch(error){ElMessage.error(error.message)}}
async function removeAnnouncement(item){if(!window.confirm(`确定删除公告“${item.title}”吗？`))return;try{const result=await api(`/admin/announcements/${item.id}`,{method:'DELETE'});ElMessage.success(result.message);await load()}catch(error){ElMessage.error(error.message)}}
function openUserAction(item,type){actionTarget.value=item;actionType.value=type;actionReason.value='';actionTyped.value='';resetPassword.value='';actionUnderstood.value=false;userActionDialog.value=true}
async function runUserAction(){if(!actionUnderstood.value||actionTyped.value!==actionConfirmText.value)return ElMessage.warning(`请输入“${actionConfirmText.value}”完成二次确认`);if(actionType.value==='reset'&&resetPassword.value.length<8)return ElMessage.warning('临时密码至少需要 8 位');actionBusy.value=true;try{let result,base=`/admin/users/${actionTarget.value.user_id||actionTarget.value.id}`;if(actionType.value==='delete')result=await api(base,{method:'DELETE',body:JSON.stringify({confirm:true,confirm_text:'删除账户',reason:actionReason.value})});else if(actionType.value==='reset')result=await api(`${base}/reset-password`,{method:'POST',body:JSON.stringify({temporary_password:resetPassword.value,confirm:true,confirm_text:'重置密码',reason:actionReason.value})});else result=await api(`${base}/status`,{method:'PATCH',body:JSON.stringify({status:actionType.value==='disable'?'disabled':'active',confirm:true,confirm_text:actionConfirmText.value,reason:actionReason.value})});ElMessage.success(result.message);userActionDialog.value=false;await load()}catch(error){ElMessage.error(error.message)}finally{actionBusy.value=false}}
onMounted(load)
</script>

<style scoped>
.admin-shell{min-height:100vh;background:#fffaf6}.admin-page{width:min(1120px,94vw);margin:0 auto;padding:42px 0 80px}.hero{margin-bottom:22px}.eyebrow{font-size:11px;letter-spacing:1.5px;color:#bd7558;font-weight:800;margin:0 0 7px}.hero h1{margin:0;color:#633e2e;font-size:32px}.hero>p:last-child{color:#96796a}.toolbar{display:flex;justify-content:space-between;align-items:center;padding:18px 0}.toolbar p{color:#927468}.announcement-card,.request-card{display:flex;justify-content:space-between;gap:18px;padding:20px 22px;margin:12px 0;border:1px solid #eeddd3;border-radius:18px;background:#fffdfb}.announcement-card b,.request-card b{color:#704330}.announcement-card p,.request-card p{white-space:pre-wrap;line-height:1.65;color:#8b6d5f;margin:7px 0}.announcement-card small{color:#b19484}.announcement-card aside,.request-card aside{display:flex;gap:8px;align-items:flex-start}.primary,.secondary,.danger{border:0;border-radius:11px;padding:9px 13px;cursor:pointer;font-weight:800;white-space:nowrap}.primary{background:#c96d42;color:#fff}.secondary{background:#f5e7df;color:#805d4e}.danger{background:#b95036;color:#fff}.table-wrap{overflow:auto;border:1px solid #eeddd3;border-radius:16px;background:#fffdfb}.block{display:block;margin-top:4px;color:#a08273}.status{padding:4px 8px;border-radius:10px;font-size:12px;font-weight:800}.status.on{color:#4a7b5a;background:#e7f4e9}.status.off{color:#a54635;background:#fbe3dd}.empty{padding:28px;text-align:center;color:#a18475}.warning-box{padding:14px;border-radius:13px;background:#fff0e8;color:#8b503c;line-height:1.65}.action-form{margin-top:15px}@media(max-width:650px){.announcement-card,.request-card,.toolbar{align-items:flex-start;flex-direction:column}.announcement-card aside,.request-card aside{width:100%}}
</style>
